(()=>{let saved;try{saved=localStorage.getItem('uniify-appearance')}catch{}document.documentElement.dataset.appearance=saved||(/workspace|onboarding|signin|signup|verify|forgot/.test(location.pathname)?'light':'dark');function sync(){document.querySelectorAll('[data-theme-toggle]').forEach(b=>{const dark=document.documentElement.dataset.appearance==='dark';b.textContent=dark?'Light mode':'Dark mode';b.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');b.setAttribute('aria-pressed',String(dark))})}document.addEventListener('DOMContentLoaded',sync);document.addEventListener('click',e=>{if(!e.target.closest('[data-theme-toggle]'))return;const next=document.documentElement.dataset.appearance==='dark'?'light':'dark';document.documentElement.dataset.appearance=next;try{localStorage.setItem('uniify-appearance',next)}catch{}sync()})})();
